export function startCSSShowroom(){
 const host=document.getElementById('scene'),wrap=document.getElementById('sceneWrap');document.getElementById('sceneLoader').classList.add('hidden');host.innerHTML='<div class="css-viewport"><div class="css-world"><div class="css-floor"></div><div class="css-back"><div class="css-back-brand">NUTZORA<small>SA-BR · HONEY, NUTS & LITTLE JOYS</small></div></div><div class="css-side left"></div></div></div>';const view=host.firstElementChild,world=view.firstElementChild;
 function piece(cls,html,transform){const el=document.createElement('div');el.className=cls;el.innerHTML=html||'';if(transform)el.style.transform=transform;world.appendChild(el);return el}
 function furniture(x,y,z,w,h,d){const el=piece('css-furniture',['front','back','top','side','other'].map(f=>`<div class="css-face ${f}"></div>`).join(''),`translate3d(${x}px,${y}px,${z}px)`);el.style.cssText+=`;--w:${w}px;--h:${h}px;--d:${d}px;--bg:#d0c3a4`;return el}
 for(const [x,type]of[[-250,'honey'],[250,'mix']])piece('css-shelf',`<strong>${type==='honey'?'MINI HONEY NUTS':'EVERYDAY NUT MIX'}</strong>`+Array.from({length:4},()=>'<div class="css-shelf-row">'+Array.from({length:8},()=>`<button class="css-mini-pack ${type}" data-pack="${type}" aria-label="${type==='honey'?'হানি নাট্টস':'নাট্ট মিক্স'} বিস্তারিত"></button>`).join('')+'</div>').join(''),`translate3d(${x}px,0,-270px)`);
 const island=furniture(0,105,-125,290,120,140);island.innerHTML+='<div class="css-island-sign">LITTLE BOX. BIG LITTLE JOYS.</div>';
 for(let i=0;i<6;i++){let type=i<3?'honey':'mix';piece(`css-hero-pack ${type}`,`<span>${type==='honey'?'Honey Nuts':'Nut Mix'}</span>`,`translate3d(${-110+i*44}px,22px,-125px)`)}
 for(const [x,type]of[[-215,'honey'],[215,'mix']]){let p=furniture(x,115,160,100,100,100);p.innerHTML+=`<div class="css-stand-label">${type==='honey'?'HONEY NUTS · 20g':'NUT MIX · 18g'}</div>`;let pack=piece(`css-hero-pack ${type}`,`<span>${type==='honey'?'Honey Nuts':'Nut Mix'}</span>`,`translate3d(${x}px,37px,160px) scale(1.6)`);pack.dataset.pack=type;pack.setAttribute('role','button');pack.tabIndex=0;pack.setAttribute('aria-label',(type==='honey'?'হানি নাট্টস':'নাট্ট মিক্স')+' 3D প্যাক বিস্তারিত')}
 for(const x of[-260,0,260])piece('css-pendant','',`translate3d(${x}px,0,-160px)`);
 for(const x of[-355,355])piece('css-plant','<div class="css-pot"></div>'+Array.from({length:7},(_,i)=>`<div class="css-leaf" style="--r:${-55+i*18}deg;--ry:${i*31}deg"></div>`).join(''),`translate3d(${x}px,0,210px)`);
 let angle=-27,walk=false,depth=0,pan=0;const mobile=()=>host.clientWidth<700;function update(){const s=walk?(mobile()?.7:1.1):(mobile()?.49:.86);world.style.transform=`translate3d(${pan}px,${walk?85:0}px,${depth}px) rotateX(${walk?-4:-18}deg) rotateY(${angle}deg) scale(${s})`}
 function enter(){walk=true;angle=0;depth=180;pan=0;view.classList.add('walking');wrap.classList.add('walking');document.querySelector('.hero-copy').classList.add('hidden');document.getElementById('sceneMode').textContent='WALK MODE';document.getElementById('sceneHint').textContent='টেনে তাকান · তীরচিহ্ন দিয়ে হাঁটুন · পণ্যে চাপ দিন';update();wrap.scrollIntoView({behavior:'smooth',block:'center'})}
 function reset(){walk=false;angle=-27;depth=0;pan=0;view.classList.remove('walking');wrap.classList.remove('walking');document.querySelector('.hero-copy').classList.remove('hidden');document.getElementById('sceneMode').textContent='3D LIVE';document.getElementById('sceneHint').textContent='↔ টেনে ঘুরে দেখুন · পণ্যে চাপ দিন';update()}
 document.getElementById('enterStore').onclick=enter;document.getElementById('homeView').onclick=reset;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{enter();angle=b.dataset.view==='honey'?-25:25;pan=b.dataset.view==='honey'?110:-110;depth=260;update()});document.getElementById('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(wrap.requestFullscreen)await wrap.requestFullscreen();else enter()}catch{enter()}};
 let down=false,last=0,moved=0;view.addEventListener('pointerdown',e=>{down=true;last=e.clientX;moved=0});view.addEventListener('pointermove',e=>{if(!down)return;const d=e.clientX-last;last=e.clientX;moved+=Math.abs(d);angle=Math.max(-65,Math.min(65,angle+d*.13));update()});view.addEventListener('pointerup',()=>down=false);view.addEventListener('pointercancel',()=>down=false);view.addEventListener('pointerleave',()=>down=false);
 function detail(el){const type=el.dataset.pack|| (el.classList.contains('mix')?'mix':'honey');window.dispatchEvent(new CustomEvent('nutzora-product',{detail:type}))}view.addEventListener('click',e=>{const el=e.target.closest('[data-pack],.css-hero-pack');if(el&&moved<10)detail(el)});view.addEventListener('keydown',e=>{const el=e.target.closest('[data-pack]');if(el&&['Enter',' '].includes(e.key)){e.preventDefault();detail(el)}});
 function move(dir){if(!walk)return;if(dir==='forward')depth=Math.min(430,depth+35);if(dir==='back')depth=Math.max(-50,depth-35);if(dir==='left')pan=Math.min(230,pan+35);if(dir==='right')pan=Math.max(-230,pan-35);update()}
 document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move(b.dataset.move));window.addEventListener('keydown',e=>{if(!walk||/INPUT|TEXTAREA/.test(document.activeElement.tagName)||document.querySelector('dialog[open]')||document.getElementById('cartDrawer').classList.contains('open'))return;const d={ArrowUp:'forward',w:'forward',ArrowDown:'back',s:'back',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'}[e.key];if(d){e.preventDefault();move(d)}});new ResizeObserver(update).observe(host);update();
}
